*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
scwin.vScrenID = 'ULDBNS22200.xml';
scwin.vMktactCd = ''; //채권시장조치구분코드
scwin.vIsuCd = '', scwin.hasAttachDoc = '';
scwin.vStdCd = '', scwin.vApplSeq = '', scwin.vNewApplSeq = '';
scwin.gBndApplId = '', scwin.gProcsStat = '0'; //처리상태코드(0:미처리,1:접수,2:반송,3:처리완료)	
scwin.vBndListProcsTpCd = 1; //채권처리구분(1:신청,2:접수)
scwin.vDtlInfoRowCount = 0;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.processGp; //접수 1, 반송 2, 처리완료 3, 수정 4, 팀장확인 6, 표준코드요청 9
scwin.gIsurCd = '';
scwin.btnStat = new Object();
scwin.vRegYn = 'N';
scwin.vViewYN = 'N';
scwin.vRowPos = 0;
scwin.vRowCount = 0;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : fn_Search
 * 설명       : 발행기관을 조회한다.
 ***********************************************/
scwin.fn_Search = function() {
    var dsNm = 'BNS_ISUR_INFO';
    var qryId = 'lds.stf.bnscommon.select.listIsurCd';
    var param = '&{P}V_ISUR_NM=' + $c.stf.getObjectValue(txb_IsurCd);
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_IsurList, dsNm, qryId, param);
    var arrPnl = [pnl_IsurSearch];
    $c.bns.ShowWinArrPnl(arrPnl, grd_IsurList);
};


/********************************************** 
 * 함수명  	 : fn_list_sync
 * 설명       : 발행기관별 SRI채권 종목을 조회한다.
 ***********************************************/
scwin.fn_list_sync = function() {
    var dsNm = 'BNSSRI_APPL_LIST';
    var qryId = '';
    var param = '';
    if (scwin.vBndListProcsTpCd == 1) {
        qryId = 'lds.stf.bnslistbzappl.select.reg_cancl.appl.list';
        //param += '&{P}V_DTL_YN='+ '';
        param += '&{P}V_ISUR_CD=' + scwin.gIsurCd;
        //param += '&{P}V_ISU_CD='+ vIsuCd;

    } else {
        qryId = 'lds.stf.bnslistbzappl.select.reg_cancl.acpt.list';
        //param += '&{P}V_BND_LIST_PROCS_TP_CD='+ vBndListProcsTpCd;
        //param += '&{P}V_MKTACT_CD='+ vMktactCd;

    }
    //fn_SearchBns(vScrenID, dts_List, dsNm, qryId, param);
    if (scwin.vBndListProcsTpCd == 2) {
        $c.bns.fn_SearchBns(scwin.vScrenID, dts_List, dsNm, qryId, param);
        $c.cm.ShowWin(grd_List2);
    } else {
        $c.bns.fn_SearchBns(scwin.vScrenID, dts_List1, dsNm, qryId, param);
        $c.cm.ShowWin(grd_List1);
    }
};



/********************************************** 
 * 함수명  	 : fn_dtl_sync
 * 설명       : 해당 종목의 상세내역을 조회한다.
 ***********************************************/
scwin.fn_dtl_sync = function() {
    var dsNm = 'BNSSRI_APPL_LIST';
    var qryId = '';
    var param = '';
    var fileDsNm = 'BNSSRI_APPL_FILE_LIST';
    var fileQryId = '';
    var fileParam = '';

    //SRI채권정보
    if (scwin.vBndListProcsTpCd == 1) {
        qryId = 'lds.stf.bnslistbzappl.select.reg_cancl.appl.dtl';
        param += '&{P}V_ISUR_CD=' + scwin.gIsurCd;
        param += '&{P}V_STD_CD=' + scwin.vStdCd;
        //param += '&{P}V_APPL_ISU_SEQ='+ vApplSeq;

    } else {
        qryId = 'lds.stf.bnslistbzappl.select.reg_cancl.acpt.dtl';
        param += '&{P}V_ISUR_CD=' + scwin.gIsurCd;
        param += '&{P}V_STD_CD=' + scwin.vStdCd;
        param += '&{P}V_APPL_ISU_SEQ=' + scwin.vApplSeq;
    }
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_DtlInfo, dsNm, qryId, param);

    //파일정보
    if (scwin.vBndListProcsTpCd == 2) {
        fileQryId = 'lds.stf.bnssri.select.sriBndMgtFileList';
        fileParam += '&{P}V_STD_CD=' + scwin.vStdCd;
        fileParam += '&{P}V_APPL_ISU_SEQ=' + scwin.vApplSeq;
        $c.bns.fn_SearchBns(scwin.vScrenID, dts_fileList, fileDsNm, fileQryId, fileParam);
    }
};



/********************************************** 
 * 함수명   : fn_SeqSearch
 * 설명       : 채권신청번호 생성
 ***********************************************/
scwin.fn_SeqSearch = function() {
    var dsNm = 'BNS_SRI_APPL_ISU_SEQ_NEXTVAL';
    var qryId = 'lds.stf.bnscommon.select.APPL_ISU_SEQ_NextVal';
    var param = '&{P}V_STD_CD=' + scwin.vStdCd;
    dts_NextSeq.SyncLoad = 'true';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_NextSeq, dsNm, qryId, param);
};


/********************************************** 
 * 함수명   : fn_InputCheck
 * 설명      : 필수 입력 값을 체크한다. 
 ***********************************************/
scwin.fn_InputCheck = function(GUBUN) {
    if (GUBUN == 'Acpt') {
        if ($c.stf.getObjectValue(edt_REG_CANCL_DD) == '') {
            $c.win.alert("[취소일]을 입력하십시오.");
            edt_REG_CANCL_DD.focus();
            return false;
        }
        if ($c.bns.fn_CheckDateObj(edt_REG_CANCL_DD, "취소일")) {
            return false;
        }
        if ($c.stf.getObjectValue(cmb_BndTpCd) == '') {
            $c.win.alert("[등록취소사유]를 입력하십시오.");
            cmb_BndTpCd.focus();
            return false;
        }
        //if (! checkMaxLength(txb_DlstRsn, 60, '폐지사유') ) return false;

        if ($c.stf.getObjectValue(txb_REG_CANCL_REL_GRND) == '') {
            $c.win.alert("[관련근거]를 입력하십시오.");
            txb_REG_CANCL_REL_GRND.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_REG_CANCL_REL_GRND, 200, '관련근거')) return false;
    } else {
        if ($c.stf.getObjectValue(edt_REG_CANCL_DD2) == '') {
            $c.win.alert("[취소일]을 입력하십시오.");
            edt_REG_CANCL_DD2.focus();
            return false;
        }
        if ($c.bns.fn_CheckDateObj(edt_REG_CANCL_DD2, "취소일")) {
            return false;
        }
        if ($c.stf.getObjectValue(cmb_BndTpCd2) == '') {
            $c.win.alert("[등록취소사유]를 입력하십시오.");
            cmb_BndTpCd2.focus();
            return false;
        }
        if ($c.stf.getObjectValue(txb_REG_CANCL_REL_GRND2) == '') {
            $c.win.alert("[관련근거]를 입력하십시오.");
            txb_REG_CANCL_REL_GRND2.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_REG_CANCL_REL_GRND2, 200, '관련근거')) return false;
    }
    return true;
};


/********************************************** 
 * 함수명   : fn_AcptProcsCheck
 * 설명      : 접수, 처리완료시 공통 체크 구문
 ***********************************************/
scwin.fn_AcptProcsCheck = function(gubun) {
    if (gubun == 'Acpt') {
        //필수입력값 체크
        if (scwin.fn_InputCheck('Acpt') == false) return 1;

        //적용일,매매일,마감일,채권마감 체크
        if ($c.bns.fn_CheckCmDataSriRegCancl(scwin.vScrenID, dts_CheckCmData, $c.stf.getObjectValue(edt_REG_CANCL_DD)) > 0) return 1;
    } else if (gubun == 'Procs') {
        //필수입력값 체크
        if (scwin.fn_InputCheck('Proc') == false) return 1;

        //적용일,매매일,마감일,채권마감 체크		
        if ($c.bns.fn_CheckCmDataSriRegCancl(scwin.vScrenID, dts_CheckCmData, $c.stf.getObjectValue(edt_REG_CANCL_DD2)) > 0) return 1;
    }
    scwin.vIsuCd = dts_DtlInfo.getCellData(1, "ISU_CD");
    scwin.hasAttachDoc = dts_DtlInfo.getCellData(1, "HAS_ATTACH_DOC");

    //변경된 데이터가 없더라도 데이터셋 전송
    dts_DtlInfo.UseChangeInfo = "False";
    return 0;
};


/********************************************** 
 * 함수명   : fn_Acpt
 * 설명       : 신청데이터를 접수 처리한다.
 ***********************************************/
scwin.fn_Acpt = function() {
    //채권신청ID생성 체크
    //if (gBndApplId == '') {
    //	alert("채권신청ID를 생성하지 못했습니다.");
    //	return;
    //}

    //접수, 처리완료 공통 체크
    if (scwin.fn_AcptProcsCheck('Acpt') > 0) return;

    //접수처리건/미처리건 확인
    var dsNm = 'BNS_COM_CD';
    var qryId = 'lds.stf.bnslistbzappl.select.reg_cancl.uncompleted';
    var param = "&{P}V_STD_CD=" + dts_DtlInfo.getCellData(1, "STD_CD");
    dts_Temp.SyncLoad = true;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_Temp, dsNm, qryId, param);
    if (dts_Temp.getCellData(1, 'VALUE') > 0) {
        $c.win.alert('등록취소 접수내역에 해당 종목이 존재합니다. \n\n[접수내역]을 확인하여 주십시요.');
        return;
    }

    //접수		
    if (!confirm("접수처리 하시겠습니까?")) return;
    var url = "/bns/IsuChgEtc.do?method=processApplAcptSriRegCancl";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    url += "&FILE_FAX=" + "ESG";
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_DtlInfo,I:pFile=dts_fileList)";
    trs_Save.Post();
};


/********************************************** 
 * 함수명   : fn_ProcsComplt
 * 설명       : 처리완료 및 수정을 처리한다.
 ***********************************************/
scwin.fn_ProcsComplt = function() {
    //접수, 처리완료 공통 체크
    if (scwin.fn_AcptProcsCheck('Procs') > 0) return;
    var url;
    if (scwin.processGp == '4') {
        //접수 후 수정 및 반송시 체크한다.			
        //if (fn_CheckModAndRet(vScrenID, dts_CheckCmData, gBndApplId) > 0) return;
        if (!confirm("수정처리 하시겠습니까?")) return;
        if (scwin.gProcsStat != "3") {
            url = "/bns/IsuChgEtc.do?method=processUpdateSriRegCancl";
        }
    } else {
        //if(! fn_EndConfirm(hasAttachDoc, '처리완료')) return;
        if (!confirm("처리완료 하시겠습니까?")) return;
        if (scwin.gProcsStat != "3") {
            url = "/bns/IsuChgEtc.do?method=processCompltSriRegCancl";
        }
    }

    //alert(gProcsStat);


    url += "&PROCS_STAT_CD=" + scwin.gProcsStat;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;

    //alert(url);

    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_DtlInfo,I:pFile=dts_fileList)";
    trs_Save.Post();
};


/********************************************** 
 * 함수명   : fn_GetCommonKey
 * 설명       : 팝업에 넘길 키데이터를 정의한다.
 ***********************************************/
scwin.fn_GetCommonKey = function(arrPar) {
    arrPar[0] = {
        //첨부문서 목록 팝업	
        BND_APPL_ID: dts_DtlInfo.getCellData(1, "BND_APPL_ID"),
        BND_LIST_PROCS_TP_CD: dts_DtlInfo.getCellData(1, "BND_LIST_PROCS_TP_CD"),
        ISU_CD: dts_DtlInfo.getCellData(1, "ISU_CD")
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/********************************************** 
 * 함수명   : fn_GetReturn
 * 설명       : 반송 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetReturn = function(arrPar) {
    arrPar[0] = {
        STD_CD: dts_DtlInfo.getCellData(1, "STD_CD"),
        APPL_ISU_SEQ: dts_DtlInfo.getCellData(1, "APPL_ISU_SEQ"),
        ISUR_NM: dts_DtlInfo.getCellData(1, "ISUR_NM"),
        ISU_NM: dts_DtlInfo.getCellData(1, "ISU_NM")
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetReturn
 * 설명       : 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetReturn = function(arrPar) {
    if ("Y" == arrPar[0].SUCCESS_YN) {
        scwin.fn_list_sync();
    }
};



/********************************************** 
 * 함수명   : fn_GetParIsuDelInfo
 * 설명       : 종목상세 목록 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParIsuDelInfo = function(arrPar) {
    arrPar[0] = {
        STD_CD: dts_DtlInfo.getCellData(1, "STD_CD"),
        BND_LIST_PROCS_TP_CD: scwin.vBndListProcsTpCd
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/********************************************** 
 * 함수명   : fn_GetParApprovFileWrt
 * 설명       : 결재파일생성 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParApprovFileWrt = function(arrPar) {
    arrPar[0] = {
        BND_APPL_ID: scwin.gBndApplId,
        BND_LIST_PROCS_TP_CD: scwin.vBndListProcsTpCd,
        BND_MKTACT_TP_CD: scwin.vMktactCd
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/********************************************** 
 * 함수명   : fn_GetParDelistRsn
 * 설명       : 상장페지 사유선택 (종목)  팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParDelistRsn = function(arrPar) {
    arrPar[0] = {
        BND_DELIST_CD: dts_DtlInfo.getCellData(1, "BND_DELIST_CD")
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetParDelistRsn
 * 설명       : 상장페지 사유선택 (종목)  팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParDelistRsn = function(arrPar) {
    var getData = arrPar[0].BND_DELIST_CD + " " + arrPar[0].DELIST_RSN_DTL;
    if (scwin.vBndListProcsTpCd == 1) {
        $c.stf.setObjectValue(txb_DlstRsn, getData);
        $c.stf.setObjectValue(txb_MemoContn, arrPar[0].MEMO);
    } else {
        $c.stf.setObjectValue(txb_DlstRsn2, getData);
        $c.stf.setObjectValue(txb_MemoContn2, arrPar[0].MEMO);
    }
};



/********************************************** 
 * 함수명   : fn_AnfeeRefnd
 * 설명       : 연부과금 환급수수료 등록 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_AnfeeRefnd = function(arrPar) {
    arrPar[0] = {
        BND_APPL_ID: scwin.gBndApplId,
        BND_LIST_PROCS_TP_CD: scwin.vBndListProcsTpCd,
        MKTACT_TP_CD: scwin.vMktactCd,
        SCREN_ID: scwin.vScrenID
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetAnfeeRefnd
 * 설명       : 연부과금 환급수수료 등록 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetAnfeeRefnd = function(arrPar) {
    scwin.vRegYn = arrPar[0].REG_YN;
    if (scwin.vRegYn == 'Y') {
        scwin.vRowPos = dts_List.getRowPosition();
        scwin.fn_list_sync();
    }
};



/********************************************** 
 * 함수명   : fn_ProcBtnStat
 * 설명       : 처리 상태가 처리완료일 경우, 처리완료 버튼 비활성화
 ***********************************************/
scwin.fn_ProcBtnStat = function() {
    if (scwin.gProcsStat == "1") {
        btn_Proc.src = "../img/bns/btn_20.gif";
        btn_Proc.setDisabled(false);
        btn_Mod.src = "../img/bns/btn_modify_n.gif";
        btn_Mod.setDisabled(false);
        //			btn_TeamleadrConfrm.src = "../img/bns/btn_21_d.gif";
        //			btn_TeamleadrConfrm.disabled = true;
        btn_Ret2.src = "../img/bns/btn_Ret_n.gif";
        btn_Ret2.setDisabled(false);
    } else if (scwin.gProcsStat == "3") {
        btn_Proc.src = "../img/bns/btn_20_d.gif";
        btn_Proc.setDisabled(true);
        btn_Mod.src = "../img/bns/btn_modify_nd.gif";
        btn_Mod.setDisabled(true);
        //			btn_TeamleadrConfrm.src = "../img/bns/btn_21.gif";
        //			btn_TeamleadrConfrm.disabled = false;
        btn_Ret2.src = "../img/bns/btn_Ret_nd.gif";
        btn_Ret2.setDisabled(true);
    }
};



/******************************************************************* 
 * 함수명   : fn_PopReturn
 * 설명     : 반송처리 팝업을 보여준다.
 * argument : object
 *******************************************************************/
scwin.fn_PopReturn = async function(grdObj) {
    $c.bns.fn_SetPopupPos(grdObj, 'E');
    await $c.frame.CreateDialogFrame("ULDBNS21901", "/bnslistbzappl/ULDBNS21901.gfm", "반송처리", obj_left, obj_top, 480, 280, "window");
};

/********************************************** 
 * 함수명   : ins_return
 * 설명       : 반송후 로직 
 ***********************************************/
scwin.ins_return = function(vRsn) {
    var url = "/bns/IsuChgEtc.do?method=updateSriBndReturnBtn";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    var param = "STD_CD=" + scwin.vStdCd;
    param += ", APPL_ISU_SEQ=" + scwin.vApplSeq;
    param += ", RET_RSN=" + vRsn;
    trs_return.Action = $c.lc.fn_encodeNSession(url);
    trs_return.KeyName = "toinb_dataid4";
    trs_return.KeyValue = "JSP(I:pInput=dts_DtlInfo)";
    trs_return.Parameters = param;
    trs_return.Post();
};


/*파일처리 시작*/
/*************************
 * 함수명   : fn_SelectAttach
 * 설명     : 파일 추가
 * argument : object
 *************************/
scwin.fn_SelectAttach = function() {
    //if (fn_InputCheck('Select') == false) return;
    if (dts_fileList.getTotalRow() == 1) {
        $c.win.alert("더이상 추가하실 수 없습니다.");
        return;
    }
    file.setValue("");
    file.open();
    if (file.getValue() != "") {
        var vFile = file.getValue();
        var vFileNm = vFile.split("\\");
        vFileNm = vFileNm[vFileNm.length - 1];
        if (vFileNm != "") {
            if (scwin.fn_CheckExtension(vFileNm)) return; // 파일 확장자 체크
            dts_fileList.insertRow();
        } else {
            return;
        }
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "ISUR_CD", scwin.gIsurCd);
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "FILE_NM", vFileNm);
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "FILE_URL", file.getValue());
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "FILE_TP_CD", '12'); //등록취소신청서
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "STD_CD", scwin.vStdCd);
        //dts_fileList.NameString(dts_fileList.RowPosition, "APPL_ISU_SEQ")  = vNewApplSeq;//새로운 신청번호는 접수버튼 누를때 생성해서 넣어줘야함

    }
};




/******************************
 * 함수명   : fn_CheckExtension
 * 설명     : 업로드 파일 확장자 체크 
 * argument : object
 *******************************/
scwin.fn_CheckExtension = function(fileNm) {
    //var fileExts = new Array(".hwp",".docx",".doc",".xls",".xlsx",".ppt",".pptx",".pdf",".gif",".jpg",".jpeg",".bmp",".tif",".txt",".drt",".dsd",".png");// 허가 확장자 목록
    var fileExts = new Array(".pdf"); // 허가 확장자 목록
    var vsFileNm = fileNm;
    var vsFileExts = vsFileNm.substr(vsFileNm.lastIndexOf("."), vsFileNm.length);
    var vsFlag = true;
    for (var i = 0; i < fileExts.length; i++) {
        if (fileExts[i] == vsFileExts) {
            vsFlag = false;
            break;
        }
    }
    if (vsFlag) {
        $c.win.alert("업로드할 수 없는 확장자입니다. 확인바랍니다.");
        return true;
    }
    return false;
};


/*************************
 * 함수명   : fn_FileDownload
 * 설명     : 파일 다운로드
 * argument : object
 *************************/
scwin.fn_FileDownload = function(row) {
    if (dts_fileList.getCellData(row, "ORGN_FILE_NM") == "") {
        return;
    } else {
        var url = "/bns/BnsAttachDocFileDownload.do";
        url += "?ATTACH_FILE_TP_CD=" + 2;
        url += "&ISUR_CD=" + dts_fileList.getCellData(row, "ISUR_CD");
        url += "&APPL_DD=" + dts_fileList.getCellData(row, "APPL_DD");
        url += "&APPL_TM=" + dts_fileList.getCellData(row, "APPL_TM");
        location.href = url;
    }
};


/*파일처리 종료*/

/********************************************** 
 * 함수명   : fn_setCheckBoxALL
 * 설명       : 그리드 체크박스 전체선택 또는 전체선택 해제
 ***********************************************/
scwin.fn_setCheckBoxALL = function(grdObj, dtsObj, bCheck) {
    var vcd = "";
    if (bCheck == '1') {
        vcd = "T";
    } else {
        vcd = "F";
    }
    grdObj.setBroadcast(false);
    for (var i = 1; i <= dtsObj.getTotalRow(); i++) {
        //if (dtsObj.NameString(i, "PROCS_STAT") != '처리완료') { //처리완료만 팀장확인 대상임
        if (dtsObj.getCellData(i, "STAT") != '처리완료' || (dtsObj.getCellData(i, "TEAMLEADER_CONFRM_DD") != "undefined" && dtsObj.getCellData(i, "TEAMLEADER_CONFRM_DD") != '-' && dtsObj.getCellData(i, "TEAMLEADER_CONFRM_DD") != '')) {
            //처리완료만 팀장확인 대상임
            dtsObj.setCellData(i, "CHK", "F");
        } else {
            dtsObj.setCellData(i, "CHK", vcd);
        }
    }
    grdObj.setBroadcast(true);
};


/********************************************** 
 * 함수명   : fn_TeamleadrConfrmAllSri (TO-BE)
 * 설명       : SRI채권 일괄 팀장확인
 ***********************************************/
scwin.fn_TeamleadrConfrmAllSri = function(nTrueCnt) {
    //담당자는 팀장확인 안됨.
