        $c.win.alert('팀장권한만 가능합니다.');
        return;
    }
    if (!window.confirm("선택하신 " + nTrueCnt + "건을 [팀장확인] 처리하시겠습니까?")) return;
    var url = "/bns/IsuChgEtc.do?method=updateSriBndTeamleadrConfrmAllBtn";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_List)";
    trs_Save.Post();
};
